<div class="panel form-panel"><p class="eyebrow">INTERNATIONAL TRANSFER</p><h2>Send money</h2><?php if($this->session->flashdata('notice')):?><p class="alert success"><?=$this->session->flashdata('notice')?></p><?php endif;?><?=form_open('transfers')?><div class="form-grid"><label>From account<select name="account_id"><?php foreach($accounts as $account):?><option value="<?=$account['id']?>"><?=$account['account_number']?> · <?=$account['currency']?></option><?php endforeach;?></select></label><label>Amount<input type="number" step="0.01" name="amount" placeholder="0.00" required></label><label>Recipient name<input name="recipient" required></label><label>Recipient account / IBAN<input name="recipient_account" required></label></div><label>Transfer note<textarea name="note" rows="3" placeholder="What is this payment for?"></textarea></label><button class="button">Review transfer</button><?=form_close()?></div>
